CREATE TABLE Users (id INT IDENTITY(1,1) PRIMARY KEY, first_name NVARCHAR(100) NOT NULL, last_name NVARCHAR(100) NOT NULL, email NVARCHAR(255) UNIQUE NOT NULL, phone_number NVARCHAR(20), password NVARCHAR(255) NOT NULL, created_at DATETIME2 DEFAULT GETDATE(), updated_at DATETIME2 DEFAULT GETDATE()); 